changeSet.sql:
CREATE OR REPLACE FUNCTION guard_practice_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (to_jsonb(NEW)-'created_by_account_id'-'name'-'review_digest') IS DISTINCT FROM (to_jsonb(OLD)-'created_by_account_id'-'name'-'review_digest') OR (NEW.created_by_account_id IS NOT NULL AND NEW.created_by_account_id IS DISTINCT FROM OLD.created_by_account_id) THEN RAISE EXCEPTION 'practice versions are immutable' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;

rollback.sql:
CREATE OR REPLACE FUNCTION guard_practice_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (to_jsonb(NEW)-'created_by_account_id') IS DISTINCT FROM (to_jsonb(OLD)-'created_by_account_id') OR (NEW.created_by_account_id IS NOT NULL AND NEW.created_by_account_id IS DISTINCT FROM OLD.created_by_account_id) THEN RAISE EXCEPTION 'practice versions are immutable' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
